INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt12037194','Furiosa: A Mad Max Saga',2024,'Action','2024-tt12037194.webp','https://www.imdb.com/title/tt12037194/','https://en.wikipedia.org/wiki/File:Furiosa_A_Mad_Max_Saga.jpg','Furiosa: A Mad Max Saga is a 2024 epic post-apocalyptic action film directed and produced by George Miller, who wrote the screenplay with Nico Lathouris. It is the fifth installment in the Mad Max franchise, and the first not focused on Max Rockatansky, instead a spinoff prequel to Mad Max: Fury Road (2015) and an origin story for Furiosa. Starring Anya Taylor-Joy and Alyla Browne as said character and set years before Fury Road, the film follows her life for over a decade, from her kidnapping by the forces of warlord Dementus (Chris Hemsworth) to her ascension to the rank of Imperator. Tom Burke also stars as Praetorian Jack, a military commander who befriends Furiosa. Several Fury Road cast members return in supporting roles, including John Howard, Nathan Jones, and Angus Sampson reprising their characters. The film begins in what can be seen as a green paradise of a solarpunk future and quickly moves to the more traditional dieselpunk, which the Mad Max franchise is known for.
Miller initially intended to shoot Furiosa back-to-back with Fury Road, but the former spent several years in development hell amidst salary disputes with Warner Bros. Pictures, Fury Road''s distributor. Several crew members from Fury Road returned for Furiosa, including Lathouris, producer Doug Mitchell, composer Tom Holkenborg, costume designer Jenny Beavan, and editor Margaret Sixel (Miller''s wife). Filming took place in Australia from June to October 2022.
Furiosa: A Mad Max Saga premiered at the 77th Cannes Film Festival on 15 May 2024. It was released theatrically in Australia on 23 May 2024 and in the United States the following day. The film received highly positive reviews from critics and multiple award nominations. It was named one of the Top Ten Films of 2024 by the National Board of Review, but was a box-office bomb, grossing $174.4 million against its budget of $168 million.','https://en.wikipedia.org/wiki/Furiosa:_A_Mad_Max_Saga','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt11389872','Kingdom of the Planet of the Apes',2024,'Action','2024-tt11389872.webp','https://www.imdb.com/title/tt11389872/','https://en.wikipedia.org/wiki/File:Kingdom_of_the_Planet_of_the_Apes_poster.jpg','Kingdom of the Planet of the Apes is a 2024 American science fiction action film directed by Wes Ball and written by Josh Friedman. It is the fourth installment in the Planet of the Apes reboot film series and the tenth film overall, serving as a standalone sequel to War for the Planet of the Apes (2017). The film stars Owen Teague, Freya Allan, Kevin Durand, Peter Macon, and William H. Macy. It takes place many generations after the events of War and follows Noa (Teague), a young chimpanzee hunter who embarks on a journey alongside Mae (Allan), a human woman, to determine the future for apes and humans alike.
Development on a new Planet of the Apes film began in April 2019, following Disney''s acquisition of 20th Century Fox, with Ball attached as writer and director that December. Much of the screenplay was written during the COVID-19 pandemic in 2020, with casting commencing in June 2022, following the screenplay''s completion. Teague was cast in the lead role that August, with the film''s title and additional casting announced in the following months. Principal photography began in October 2022 in Sydney and wrapped in February 2023, with a budget of $120–160 million.
Kingdom of the Planet of the Apes premiered at the TCL Chinese Theatre in Los Angeles on May 2, 2024, and was released by 20th Century Studios in the United States on May 10. The film grossed over $397 million worldwide and received generally positive reviews from critics, though it was ultimately deemed inferior to its predecessors. It received a nomination for Best Visual Effects at the 97th Academy Awards. A sequel is in development.','https://en.wikipedia.org/wiki/Kingdom_of_the_Planet_of_the_Apes','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt14539740','Godzilla x Kong: The New Empire',2024,'Action','2024-tt14539740.webp','https://www.imdb.com/title/tt14539740/','https://en.wikipedia.org/wiki/File:Godzilla_x_kong_the_new_empire_poster.jpg','Godzilla x Kong: The New Empire is a 2024 American monster film directed and co-written by Adam Wingard. Produced by Legendary Pictures and distributed by Warner Bros. Pictures, it is a sequel to Godzilla vs. Kong (2021) and the fifth film in Legendary''s Monsterverse franchise, as well as the 38th film in the Godzilla franchise and the 13th in the King Kong franchise. The film stars Rebecca Hall, Brian Tyree Henry, Dan Stevens, Kaylee Hottle, Alex Ferns, and Fala Chen. Hall, Henry, and Hottle reprise their roles from the previous film; it is Hottle''s final role before her death in 2026. In the film, Kong encounters more of his species in the Hollow Earth and must unite again with Godzilla to stop the tyrannical Skar King and the powerful, frost-breathing Shimo from invading the Earth''s surface.
Following the box office and streaming success of Godzilla vs. Kong during the COVID-19 pandemic, Legendary announced a sequel in March 2022 and that filming would commence later that year. In May 2022, it was announced that Wingard would return to direct and Stevens had been cast as a lead. Filming began in July 2022 in Gold Coast, Australia, and finished in November 2022.
Godzilla x Kong: The New Empire premiered at Grauman''s Chinese Theatre on March 25, 2024, and was released in the United States on March 29. The film received mixed reviews from critics, with many comparing it unfavorably to Godzilla Minus One, which had been released four months prior. It grossed $572.5 million worldwide against a production budget of $135–150 million, becoming the eighth-highest-grossing film of 2024 and the highest-grossing film of the Monsterverse, as well as in the Godzilla and King Kong franchises.
A sequel, Godzilla x Kong: Supernova, is planned for March 26, 2027.','https://en.wikipedia.org/wiki/Godzilla_x_Kong:_The_New_Empire','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt6263850','Deadpool & Wolverine',2024,'Action','2024-tt6263850.webp','https://www.imdb.com/title/tt6263850/','https://en.wikipedia.org/wiki/File:Deadpool_%26_Wolverine_poster.jpg','Deadpool & Wolverine is a 2024 American superhero film based on Marvel Comics featuring the characters Deadpool and Wolverine. Produced by Marvel Studios, Maximum Effort, and 21 Laps Entertainment, and distributed by Walt Disney Studios Motion Pictures, it is the 34th film in the Marvel Cinematic Universe (MCU) and the sequel to Deadpool (2016) and Deadpool 2 (2018). The film was directed by Shawn Levy, who wrote the screenplay with Ryan Reynolds, Rhett Reese, Paul Wernick, and Zeb Wells. Reynolds and Hugh Jackman respectively star as Wade Wilson / Deadpool and Logan / Wolverine, alongside Emma Corrin, Morena Baccarin, Rob Delaney, Leslie Uggams, Aaron Stanford, and Matthew Macfadyen. In the film, Deadpool works with a reluctant Wolverine from another universe to stop the Time Variance Authority (TVA) from destroying his own universe.
Development on a third Deadpool film began at 20th Century Fox by November 2016, but was moved to Marvel Studios when Fox was acquired by Disney in March 2019. Wendy Molyneux and Lizzie Molyneux-Logelin joined in November 2020 as writers. Levy was hired to direct in March 2022, when Reese and Wernick returned from the previous films for rewrites. The creative team had difficulty settling on a story until Jackman decided to reprise his role as Wolverine from Fox''s X-Men film series in August 2022. Several other actors from the X-Men films and other Marvel productions also returned as part of a multiverse story, which serves as a tribute to Fox''s Marvel films. Filming began in May 2023, taking place at Pinewood Studios, Bovingdon Studios, and Norfolk in England as well as Los Angeles. Production was suspended in July due to the 2023 SAG-AFTRA strike. Filming resumed in November and wrapped in January 2024. The title was revealed a month later. The film''s soundtrack features an original score by Rob Simonsen and numerous existing songs, including Madonna''s "Like a Prayer" for key sequences. Deadpool & Wolverine is the first R-rated MCU film, retaining that rating from the prior Deadpool films.
Deadpool & Wolverine premiered on July 22, 2024, at the David H. Koch Theater in New York City, and was released in the United States on July 26 as part of Phase Five of the MCU. Critics praised the performances of Reynolds and Jackman as well as the humor, but were less positive about the film overall. It was a commercial success, grossing $1.338 billion worldwide and becoming the second-highest-grossing film of 2024, the highest-grossing R-rated film, and the 20th-highest-grossing film at the time. With a net production budget of $429 million, Deadpool & Wolverine is believed to be one of the most expensive films ever made. It received various accolades. A sequel is in development.','https://en.wikipedia.org/wiki/Deadpool_%26_Wolverine','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt12584954','Twisters',2024,'Action','2024-tt12584954.webp','https://www.imdb.com/title/tt12584954/','https://en.wikipedia.org/wiki/File:Twisters_Official_US_Theatrical_Poster.jpg','Twisters is a 2024 American disaster film directed by Lee Isaac Chung and written by Mark L. Smith, based on a story by Joseph Kosinski. A standalone sequel to Twister (1996), the ensemble cast includes Daisy Edgar-Jones, Glen Powell, Anthony Ramos, Brandon Perea, Maura Tierney, and Sasha Lane. It follows clashing groups of storm chasers who investigate a tornado outbreak in Oklahoma.
Talks for a sequel to Twister began in 2020, with Kosinski pitching an idea to Warner Bros. Helen Hunt, who starred in the original, had also expressed interest in developing a follow-up that was ultimately rejected. Several other directors were approached before Chung was hired in December 2022. The cast joined in early-2023 and filming took place around Oklahoma that summer, with a brief hiatus due to the SAG-AFTRA strike.
Twisters premiered at the Empire Leicester Square in London on July 8, 2024, and was released internationally by Warner Bros. Pictures on July 10, and in the United States and Canada by Universal Pictures on July 19. It received generally positive reviews from critics and grossed over $372 million worldwide on a $155 million budget.','https://en.wikipedia.org/wiki/Twisters_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
