INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt9218128','Gladiator II',2024,'Action','2024-tt9218128.webp','https://www.imdb.com/title/tt9218128/','https://en.wikipedia.org/wiki/File:Gladiator_II_%282024%29_poster.jpg','Gladiator II is a 2024 epic historical film directed and produced by Ridley Scott. The sequel to Gladiator (2000), it was written by David Scarpa based on a story he wrote with Peter Craig. The film was produced by Scott Free Productions and Red Wagon Entertainment and distributed by Paramount Pictures. It stars Paul Mescal, Pedro Pascal, Joseph Quinn, Fred Hechinger, Connie Nielsen, and Denzel Washington. Derek Jacobi and Nielsen reprise their roles from the first film, with Mescal replacing Spencer Treat Clark. Mescal portrays Lucius Verus Aurelius, the exiled Prince of Rome, who becomes a prisoner of war and fights as a gladiator for Macrinus, a former slave who plots to overthrow the twin emperors Caracalla and Geta.
A sequel to Gladiator was discussed as early as June 2001, with David Franzoni and John Logan set to return as screenwriters. Over the next few years, Scott offered occasional updates, including the possible involvement of the original film''s lead actor, Russell Crowe, along with plot ideas about the Roman afterlife and different historical time periods. Development was halted when DreamWorks Pictures was sold to Paramount in 2006. The film was finally announced in 2018, and Mescal was cast in the lead role in January 2023, with a script by David Scarpa. Filming took place between June 2023 and January 2024, with a five-month delay due to the 2023 Hollywood labor disputes.
Gladiator II premiered in Sydney, Australia, on October 30, 2024, and was released in the United Kingdom on November 15 and in the United States on November 22. The film received generally positive reviews from critics, although it was considered inferior to its predecessor, and grossed $462.2 million worldwide. It received two nominations at the 82nd Golden Globe Awards: Cinematic and Box Office Achievement and Best Supporting Actor for Washington, and was nominated for Best Costume Design at the 97th Academy Awards.','https://en.wikipedia.org/wiki/Gladiator_II','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt1684562','The Fall Guy',2024,'Action','2024-tt1684562.webp','https://www.imdb.com/title/tt1684562/','https://en.wikipedia.org/wiki/File:The_Fall_Guy_%282024%29_poster.jpg','The Fall Guy is a 2024 American action comedy film directed by David Leitch and written by Drew Pearce, loosely based on the 1980s TV series. The film stars Ryan Gosling and Emily Blunt. The cast also features Aaron Taylor-Johnson, Hannah Waddingham, Teresa Palmer, Stephanie Hsu, and Winston Duke. The plot follows a stuntman working on his former girlfriend''s directorial debut action film, only to find himself involved in a conspiracy surrounding the film''s main actor. 
The Fall Guy premiered at SXSW on March 12, 2024, and it was released in the United States on May 3 by Universal Pictures. The film received generally positive reviews from critics, yet it underperformed at the box office, grossing $181 million worldwide against a $125–150 million production budget and losing the studio around $50 million.','https://en.wikipedia.org/wiki/The_Fall_Guy_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
