INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt18259086','Sonic the Hedgehog 3',2024,'Action','2024-tt18259086.webp','https://www.imdb.com/title/tt18259086/','https://en.wikipedia.org/wiki/File:Sonic_the_Hedgehog_3_film_poster.jpg','Sonic the Hedgehog 3 is a 2024 action-adventure comedy film based on the Sonic video game series. It is the third in the Sonic film series, it was directed by Jeff Fowler and written by Pat Casey, Josh Miller, and John Whittington. Jim Carrey, Ben Schwartz, Lee Majdoub,  Natasha Rothwell, Adam Pally, Shemar Moore, Colleen O''Shaughnessey, James Marsden, Tika Sumpter, and Idris Elba reprise their roles, with Krysten Ritter and Keanu Reeves joining the cast. In the film, Sonic, Tails, and Knuckles face Shadow the Hedgehog (Reeves), who allies with the mad scientists Ivo and Gerald Robotnik to pursue revenge against humanity.
Sonic the Hedgehog 3 was announced in February 2022 during ViacomCBS''s investor event before the release of Sonic the Hedgehog 2, with Fowler, the producer, and the writers returning. The plot draws elements from the video games Sonic Adventure 2 (2001) and Shadow the Hedgehog (2005), becoming darker than prior installments yet mindful of fan expectations and family appeal. Among the cast, Carrey returned for his appreciation for Ivo and the financial incentive, Reeves joined as Shadow due to his natural darkness and especially his performance in the John Wick films, and Alyla Browne was cast due to her performances in several George Miller films.
Due to the 2023 SAG-AFTRA strike, filming for animated characters began in September 2023, while filming with actors began that November in London, and production ended by March 2024. Brandon Trost returned as cinematographer. Animation for the film was produced in-house and with work split across five other external vendors, in tandem with the Knuckles series, with studio ownership of the assets making this possible. Tom Holkenborg returned to compose the original score, which incorporated the Crush 40 song "Live & Learn" from Sonic Adventure 2, and the singer Jelly Roll released the original song "Run It" to support the soundtrack.
Sonic the Hedgehog 3 premiered at the Empire Leicester Square in London on December 10, 2024, and was released by Paramount Pictures in the United States on December 20. It received generally positive reviews from critics, with praise for Carrey and Reeves''s performances. The film was a box office success, grossing $492 million on a budget of $122 million, becoming the highest-grossing film in the franchise, the second highest-grossing video game film at the time of release, and the tenth-highest-grossing film of the year. Carrey won Favorite Villain at the 2025 Kids'' Choice Awards. Sonic the Hedgehog 4 is scheduled for March 19, 2027.','https://en.wikipedia.org/wiki/Sonic_the_Hedgehog_3_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt15239678','Dune: Part Two',2024,'Sci-Fi','2024-tt15239678.webp','https://www.imdb.com/title/tt15239678/','https://en.wikipedia.org/wiki/File:Dune_Part_Two_poster.jpeg','Dune: Part Two is a 2024 American epic space opera film directed by Denis Villeneuve, from a screenplay he wrote with Jon Spaihts. It is a sequel to Dune (2021), is the second film in a two-part adaptation of Frank Herbert''s 1965 science fiction novel Dune, and is the second of a trilogy of films developed by Legendary Pictures. Timothée Chalamet leads an ensemble cast as Paul Atreides, an exiled monarch who allies with the Fremen to overthrow House Harkonnen as part of a quest to become a messianic figure. Villeneuve produced Dune: Part Two with his wife and business partner Tanya Lapointe, Mary Parent and Cale Boyter of Legendary Pictures, and Patrick McCormick. Funding came from a distribution agreement between Legendary and Warner Bros. Pictures, as well as tax subsidies from Hungarian, Jordanian, and Abu Dhabi governments. 
Parent and Boyter pursued the idea of a Dune film after obtaining rights to the novel in 2016. Villeneuve''s deal with Legendary mandated the book''s adaptation in two films. A sequel was approved in October 2021, and production started almost immediately. Villeneuve intended for Dune: Part Two to explore Paul''s evolution into an increasingly unscrupulous character. Principal photography took place in Hungary, Italy, Jordan, Namibia, and the United Arab Emirates from July to December 2022. Creative decisions exemplified the production''s expanded scope and changes in visual presentation, such as shooting partially in black-and-white infrared light. Hans Zimmer composed the film''s soundtrack, building upon his earlier work in Dune.
Dune: Part Two premiered in Mexico City on February 6, 2024, and was released globally the week of March 1. The film was a critical and commercial success; it became 2024''s seventh highest-grossing film at the box office with $715 million, and was chosen as one of the best ten films of the year by the American Film Institute. Critics praised Dune: Part Two for its onscreen world and acting, though some debated the themes and plot development. The film was nominated for five awards at the 97th Academy Awards (including Best Picture), winning two, and received numerous accolades mostly for technical achievement. A sequel based on Herbert''s 1969 novel Dune Messiah, Dune: Part Three, is scheduled for release on December 18, 2026.','https://en.wikipedia.org/wiki/Dune:_Part_Two','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt18412256','Alien: Romulus',2024,'Sci-Fi','2024-tt18412256.webp','https://www.imdb.com/title/tt18412256/','https://en.wikipedia.org/wiki/File:Alien_Romulus_2024_%28poster%29.jpg','Alien: Romulus is a 2024 science fiction horror film directed by Fede Álvarez, who co-wrote the script with Rodo Sayagues. It is the seventh installment in the Alien film series, set between the events of Alien (1979) and Aliens (1986). The film stars Cailee Spaeny, David Jonsson, Archie Renaux, Isabela Merced, Spike Fearn, and Aileen Wu as six downtrodden young space colonists who encounter hostile creatures while scavenging a derelict space station from which they plan to steal cryostasis chambers to navigate to another planet.
At CinemaCon in April 2019, 20th Century Studios (then-named 20th Century Fox) announced plans to produce future Alien films. Álvarez was attached as director in March 2022, and Spaeny joined as the lead later that year. Filming took place from March to July 2023.
Alien: Romulus premiered in Los Angeles on August 12, 2024, and was theatrically released in the United States by 20th Century Studios on August 16. The film grossed $350.9 million worldwide and received generally positive reviews from critics. It received several industry nominations, namely for its technical aspects, including an Academy Award nomination for Best Visual Effects. A sequel is in development.','https://en.wikipedia.org/wiki/Alien:_Romulus','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
