INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt23137904','Rebel Moon – Part Two: The Scargiver',2024,'Sci-Fi','2024-tt23137904.webp','https://www.imdb.com/title/tt23137904/','https://en.wikipedia.org/wiki/File:Rebel_Moon_%E2%80%93_Part_Two_The_Scargiver_poster.jpg','Rebel Moon – Part Two: The Scargiver is a 2024 American space opera film directed by Zack Snyder from a screenplay he co-wrote with Kurt Johnstad and Shay Hatten. A direct sequel to Rebel Moon – Part One: A Child of Fire (2023), the film takes place on the moon of Veldt where Kora and the crew of warriors ventures to help the farmers to defend and fight for their home against the Motherworld. Sofia Boutella, Djimon Hounsou, Ed Skrein, Michiel Huisman, Doona Bae, Ray Fisher, Staz Nair, Fra Fee, Elise Duffy, Charlotte Maggi, Stuart Martin, Cary Elwes, and Anthony Hopkins reprise their roles from the first film.
A week after it began a limited theatrical run in the U.S., Netflix released Rebel Moon – Part Two: The Scargiver on April 19, 2024. Like its predecessor, the film received generally negative reviews from critics. An R-rated director''s cut, titled Rebel Moon – Chapter Two: Curse of Forgiveness, was released on August 2, 2024.  Like the previous installment, the director''s cut received mixed reviews, but it was generally considered to be an improvement over the original.','https://en.wikipedia.org/wiki/Rebel_Moon_%E2%80%93_Part_Two:_The_Scargiver','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
