INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt5040012','Nosferatu',2024,'Horror','2024-tt5040012.webp','https://www.imdb.com/title/tt5040012/','https://en.wikipedia.org/wiki/File:Nosferatu_IMAX_poster_2024.jpg','Nosferatu is a 2024 American Gothic horror film written and directed by Robert Eggers. It is a remake of Nosferatu: A Symphony of Horror (1922), which was in turn inspired by Bram Stoker''s novel Dracula (1897); the film combines elements of both. It stars Bill Skarsgård, Nicholas Hoult, Lily-Rose Depp, Aaron Taylor-Johnson, Emma Corrin, and Willem Dafoe.
Development began in 2015, when Eggers planned to make it his second film; he described it as a passion project, but eventually opted to delay its production. Skarsgård and Depp were cast in lead roles in September 2022. Filming took place primarily at Barrandov Studios in Prague between February and May 2023.
Nosferatu had its world premiere in Berlin on December 2, 2024, and was theatrically released in the United States by Focus Features on December 25. The film received positive reviews from critics and was a commercial success, grossing $182 million worldwide on a $50 million budget, becoming Eggers'' highest-grossing film. At the 97th Academy Awards, the film earned nominations for Best Cinematography, Best Costume Design, Best Production Design, and Best Makeup and Hairstyling.','https://en.wikipedia.org/wiki/Nosferatu_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt17526714','The Substance',2024,'Horror','2024-tt17526714.webp','https://www.imdb.com/title/tt17526714/','https://en.wikipedia.org/wiki/File:The_Substance_poster.jpg','The Substance is a 2024 body horror film written and directed by Coralie Fargeat. It follows a fading celebrity (Demi Moore) who is fired by her producer (Dennis Quaid) due to her age and uses a black market drug that creates a younger woman (Margaret Qualley) with unexpected side effects.
Fargeat wrote the screenplay to explore societal pressures surrounding women''s bodies and aging. Principal photography took place in France from August to October 2022. The film is noted for its use of satire and grotesque, hyperrealistic imagery, accomplished through prosthetic makeup and other practical effects, including bodysuits, puppetry, dummies, and approximately 21,000 liters (5,500 U.S. gallons) of theatrical blood. Originally set for distribution by Universal Pictures, the rights were later acquired by Mubi after a dispute between Fargeat and Universal over final cut privilege.
The Substance premiered at the 77th Cannes Film Festival on May 19, 2024, where it won Best Screenplay and was nominated for the Palme d''Or. The film was theatrically released in the United Kingdom and the United States on September 20, 2024, and in France on November 6, 2024. It received widespread acclaim, with particular praise for Fargeat''s writing and directing, the special effects, and Moore''s performance. At the box office, the film grossed $77–82 million on a budget of $18 million, becoming Mubi''s highest-grossing film. Moore''s performance earned her a Golden Globe Award, Critics'' Choice Award, and Screen Actors Guild Award, as well as nominations for an Academy Award and BAFTA Award. The film also received nominations for Best Picture and Best Director at the Academy Awards, Critics'' Choice and Golden Globes.','https://en.wikipedia.org/wiki/The_Substance','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
