Fly Me to the Moon premiered on July 8, 2024, at AMC Lincoln Square in New York City, New York, and was released in theaters on July 12. Originally planned for a streaming release on Apple TV+, it was moved to a theatrical release after positive early test screenings. The film received generally positive reviews from critics. It grossed $42 million worldwide on a production budget of $100 million.','https://en.wikipedia.org/wiki/Fly_Me_to_the_Moon_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
