INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt28607951','Anora',2024,'Drama','2024-tt28607951.webp','https://www.imdb.com/title/tt28607951/','https://en.wikipedia.org/wiki/File:Anora_%282024_film%29_poster.jpg','Anora is a 2024 American romantic comedy-drama film written, directed, produced, and edited by Sean Baker. It stars Mikey Madison as Anora "Ani" Mikheeva, a lap dancer from New York who marries the wealthy son of a Russian oligarch played by Mark Eydelshteyn. The supporting cast includes Yura Borisov, Karren Karagulian, Vache Tovmasyan, Darya Ekamasova, and Aleksei Serebryakov.
Anora premiered at the 77th Cannes Film Festival on May 21, 2024, where it received critical acclaim and won the Palme d''Or. It was released theatrically on October 18, 2024, by Neon, with Focus Features releasing in other territories. It grossed $59.3 million worldwide against a $6 million budget, making it Baker''s highest-grossing film.
Anora received numerous accolades and was named one of the top ten films of 2024 by the National Board of Review and the American Film Institute. It received six nominations at the 97th Academy Awards, winning five for Best Picture, Best Director, Best Actress (Madison), Best Original Screenplay, and Best Film Editing. It is one of only four films to win both the Palme d''Or and the Academy Award for Best Picture. Anora won for International Movie at the 70th David di Donatello awards, and received seven nominations at the 78th British Academy Film Awards, winning two; five at the 82nd Golden Globe Awards; and three at the 31st Screen Actors Guild Awards.','https://en.wikipedia.org/wiki/Anora','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
