INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt17279496','Civil War',2024,'Drama','2024-tt17279496.webp','https://www.imdb.com/title/tt17279496/','https://en.wikipedia.org/wiki/File:Civil_War_2024_film_poster.jpeg','Civil War is a 2024 dystopian war-thriller film written and directed by Alex Garland, and starring Kirsten Dunst, Wagner Moura, Cailee Spaeny, Stephen McKinley Henderson, Sonoya Mizuno, and Nick Offerman. Set during a second American civil war fought between a despotic federal government and secessionist movements, the plot follows a group of war journalists traveling from New York City to Washington, D.C., to interview the president of the United States before rebels take the capital city. Principal photography began in Atlanta, Georgia, in 2022, with production moving to London later in the year.
Civil War premiered at South by Southwest on March 14, 2024, and was released in the United States by A24 and in the United Kingdom by Entertainment Film Distributors on April 12, 2024. With a budget of $50 million, Civil War was A24''s most expensive film at the time. The film grossed $127 million, and received generally positive reviews from critics.','https://en.wikipedia.org/wiki/Civil_War_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt8999762','The Brutalist',2024,'Drama','2024-tt8999762.webp','https://www.imdb.com/title/tt8999762/','https://en.wikipedia.org/wiki/File:TheBrutalist2024.png','The Brutalist is a 2024 epic period drama film directed and produced by Brady Corbet, who co-wrote the screenplay with Mona Fastvold. It stars Adrien Brody as a Jewish-Hungarian architect and severely traumatized Holocaust survivor who emigrates to the United States, where he struggles to recover and get his life back on track. The cast also features Felicity Jones, Guy Pearce, Joe Alwyn, Raffey Cassidy, Stacy Martin, Emma Laird, Isaach de Bankolé, and Alessandro Nivola. The film was shot using the VistaVision format which had been originally developed in the 1950s, and was the first film shot in the format since One-Eyed Jacks in 1961.
A co-production of the United States, the United Kingdom, and Hungary, The Brutalist premiered at the 81st Venice International Film Festival on September 1, 2024, where Corbet was awarded the Silver Lion for Best Direction. It was released in the United States by A24 on December 20, 2024; in Hungary by UIP-DunaFilm on January 23, 2025; and in the United Kingdom by Focus Features through Universal Pictures International on January 24, 2025.
The film received critical acclaim and grossed $50.4 million against a $9.6 million budget. Among multiple accolades, the film earned ten nominations at the 97th Academy Awards, including Best Picture, winning for Best Cinematography, Best Original Score, and Best Actor for Brody. At the 82nd Golden Globe Awards, it won three awards, including Best Motion Picture – Drama. It was named one of the top ten films of 2024 by the American Film Institute.','https://en.wikipedia.org/wiki/The_Brutalist','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt20215234','Conclave',2024,'Drama','2024-tt20215234.webp','https://www.imdb.com/title/tt20215234/','https://en.wikipedia.org/wiki/File:Conclave_film_poster.jpg','Conclave is a 2024 political thriller film directed by Edward Berger and written by Peter Straughan, based on the 2016 novel by Robert Harris. The film stars Ralph Fiennes, Stanley Tucci, John Lithgow, Sergio Castellitto, and Isabella Rossellini. In the film, Cardinal Thomas Lawrence (Fiennes) organizes a conclave to elect the next pope and finds himself investigating secrets and scandals about the major candidates.
After premiering at the 51st Telluride Film Festival on 30 August 2024, Conclave was released in theaters in the United States by Focus Features on 25 October 2024 and in the United Kingdom by Black Bear UK on 29 November 2024. The film received positive reviews from critics, who praised the performances, directing, screenplay, and cinematography. The film has grossed $128 million worldwide on a $20 million production budget. The film experienced a resurgence in popularity following the death of Pope Francis in April 2025 and the subsequent conclave in May that resulted in the election of Pope Leo XIV, who reportedly saw the film.
Conclave was named one of the top ten films of 2024 by the National Board of Review and the American Film Institute. Among other accolades, it won four awards at the 78th British Academy Film Awards (tying The Brutalist for most of the ceremony), including Best Film, and also won the Golden Globe Award for Best Screenplay and the Screen Actors Guild Award for Outstanding Performance by a Cast in a Motion Picture. At the 97th Academy Awards, it received eight nominations, including Best Picture, and won Best Adapted Screenplay.','https://en.wikipedia.org/wiki/Conclave_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt23055660','Nickel Boys',2024,'Drama','2024-tt23055660.webp','https://www.imdb.com/title/tt23055660/','https://en.wikipedia.org/wiki/File:Nickel_Boys_film_poster.jpg','Nickel Boys is a 2024 American historical drama film based on the 2019 novel The Nickel Boys by Colson Whitehead. It was directed by RaMell Ross, who wrote the screenplay with Joslyn Barnes. Starring Ethan Herisse, Brandon Wilson, Hamish Linklater, Fred Hechinger, Daveed Diggs, Jimmie Fails, and Aunjanue Ellis-Taylor, the story follows two African-American boys, Elwood (Herisse) and Turner (Wilson), who are sent to an abusive reform school in 1960s Florida. The film is inspired by the Dozier School for Boys, a now-closed Florida reform school notorious for its abusive treatment of students.
The film was shot from a first-person point-of-view, with filming taking place in Louisiana in late 2022. It premiered at the 51st Telluride Film Festival on August 30, 2024, and had a limited theatrical release by Amazon MGM Studios on December 13, 2024. It was named one of the top 10 films of 2024 by the American Film Institute and received numerous accolades, including the award for Best Cinematography at the 40th Independent Spirit Awards, a Best Motion Picture – Drama nomination at the 82nd Golden Globe Awards and two nominations at the 97th Academy Awards for Best Picture and Best Adapted Screenplay. IndieWire named it the best film of the 2020s, as of 2025, and it has been cited by others as among the best of the 21st century.','https://en.wikipedia.org/wiki/Nickel_Boys','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt20221436','Emilia Pérez',2024,'Drama','2024-tt20221436.webp','https://www.imdb.com/title/tt20221436/','https://en.wikipedia.org/wiki/File:Emilia_P%C3%A9rez_film_poster.png','Emilia Pérez (Latin American Spanish: [eˈmilja ˈpeɾes]) is a 2024 Spanish-language French musical crime film written and directed by Jacques Audiard. It is based on Audiard''s opera libretto of the same name, which he loosely adapted from a chapter of the 2018 novel Écoute by French writer Boris Razon. The film follows a Mexican cartel leader (Karla Sofía Gascón) who aims to disappear and transition into a woman with the help of a lawyer (Zoe Saldaña). Selena Gomez, Adriana Paz, Mark Ivanir, and Édgar Ramírez also appear in starring roles.
Emilia Pérez had its world premiere on 18 May 2024 at the 77th Cannes Film Festival, where it won the Jury Prize and the Best Actress award for its female ensemble. It was theatrically released by Pathé in France on 21 August 2024. The film received generally positive reviews from critics in the United States and Europe, who praised the direction, music, performances and themes, but received backlash on multiple fronts. In Mexico, the film was panned by both audiences and critics, who criticized its cultural misrepresentation, songwriting, use of stereotypes, and Spanish dialogue. LGBTQ commentators were also critical of its depiction of transgender people.
Despite the polarized response, Emilia Pérez earned numerous accolades. At the 97th Academy Awards, the film led with 13 nominations and won two: Best Supporting Actress for Saldaña and Best Original Song for "El Mal". At the 82nd Golden Globe Awards, the film won four awards, including Best Motion Picture – Musical or Comedy and Best Motion Picture – Non-English Language, from 10 nominations. It also received 11 nominations at the 78th British Academy Film Awards, including Best Film, winning two.','https://en.wikipedia.org/wiki/Emilia_P%C3%A9rez','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt11563598','A Complete Unknown',2024,'Drama','2024-tt11563598.webp','https://www.imdb.com/title/tt11563598/','https://en.wikipedia.org/wiki/File:A_Complete_Unknown_poster.jpg','A Complete Unknown is a 2024 American biographical film about the early career of American singer-songwriter Bob Dylan, directed by James Mangold, written by Mangold and Jay Cocks, and loosely based on the 2015 book Dylan Goes Electric! by Elijah Wald. A Complete Unknown examines the period of 1961–1965, beginning with Dylan''s start as an American folk singer, and ending with his controversial use of electric instruments at the 1965 Newport Folk Festival. Dylan is portrayed by Timothée Chalamet, who also produced the film. Edward Norton, Elle Fanning, Monica Barbaro, Boyd Holbrook, Dan Fogler, Norbert Leo Butz, Eriko Hatsune, Big Bill Morganfield, Will Harrison, and Scoot McNairy appear in supporting roles.
A Complete Unknown premiered at the Dolby Theatre in Los Angeles on December 10, 2024, and was released in the United States by Searchlight Pictures on December 25. It grossed $140.5 million worldwide and received generally positive reviews. It was named one of the top ten  films of 2024 by the American Film Institute and the National Board of Review. The National Board of Review also awarded Fanning Best Supporting Actress.
The film earned eight nominations at the 97th Academy Awards, including Best Picture, Best Director, Best Actor (Chalamet), Best Supporting Actor (Norton), and Best Supporting Actress (Barbaro). It received three nominations at the 82nd Golden Globe Awards (including Best Motion Picture – Drama), four at the 31st Screen Actors Guild Awards (winning Best Actor for Chalamet), and six at the British Academy Film Awards (including Best Film).','https://en.wikipedia.org/wiki/A_Complete_Unknown','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
