INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt28082769','September 5',2024,'Drama','2024-tt28082769.webp','https://www.imdb.com/title/tt28082769/','https://www.themoviewaffler.com/2024/10/first-trailer-and-poster-for-munich-olympics-drama-september-5.html?m=1','September 5 is a 2024 German historical drama thriller film directed, co-written, and produced by Tim Fehlbaum. The ensemble cast includes Peter Sarsgaard, John Magaro, Ben Chaplin, and Leonie Benesch. The film chronicles the Munich massacre of 1972 from the perspective of the ABC Sports crew and their coverage of the events.
The film premiered at the 81st Venice International Film Festival on 29 August 2024, and was released in Germany by Constantin Film on 9 January 2025. September 5 received positive reviews from critics and won several accolades, including nine Lolas. The film also received nominations for Best Original Screenplay at the 97th Academy Awards, and Best Motion Picture – Drama at the 82nd Golden Globe Awards.','https://en.wikipedia.org/wiki/September_5_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
