INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt30057084','Babygirl',2024,'Drama','2024-tt30057084.webp','https://www.imdb.com/title/tt30057084/','https://en.wikipedia.org/wiki/File:Babygirl_%28film_poster%29.png','Babygirl is a 2024 American erotic thriller film written, directed, and produced by Halina Reijn. The film stars Nicole Kidman as a high-powered CEO who puts her career and family on the line when she begins an affair with a much younger intern (Harris Dickinson). Sophie Wilde and Antonio Banderas also star.
Babygirl premiered at the 81st Venice International Film Festival on August 30, 2024, where Kidman won the Volpi Cup for Best Actress, followed by a premiere at the 2024 Toronto International Film Festival on September 10, 2024, with a wide theatrical release by A24 on December 25, 2024. It received positive reviews and became a box office success, grossing $64.7 million on a $20 million budget. It was named one of the top ten films of 2024 by the National Board of Review, where Kidman was also awarded the Best Actress prize.','https://en.wikipedia.org/wiki/Babygirl','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
