INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt24176060','Queer',2024,'Drama','2024-tt24176060.webp','https://www.imdb.com/title/tt24176060/','https://en.wikipedia.org/wiki/File:Queer_%282024%29_film_poster.jpg','Queer (titled on-screen as William S. Burroughs'' Queer) is a 2024 period romantic drama film directed by Luca Guadagnino from a screenplay by Justin Kuritzkes, based on the 1985 novella by William S. Burroughs. Set in 1950s Mexico City and Ecuador, the film follows an outcast American expatriate (Daniel Craig) who becomes infatuated with a much younger man (Drew Starkey); Jason Schwartzman, Henry Zaga, and Lesley Manville also star.
Queer premiered at the 81st Venice International Film Festival on September 3, 2024, where it played in-competition for the Golden Lion. It was given a limited theatrical release in the United States on November 27, by A24, and was released nationwide on December 13. The film has received generally positive reviews from critics and was named one of the Top Ten Films of 2024 by the National Board of Review, where Craig was awarded the Best Actor prize. Craig was also nominated for the Golden Globe, the Critics'' Choice, and the Screen Actors Guild awards for his performance.','https://en.wikipedia.org/wiki/Queer_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
