INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt22893404','Maria',2024,'Drama','2024-tt22893404.webp','https://www.imdb.com/title/tt22893404/','https://en.wikipedia.org/wiki/File:Maria_%282024_film%29.jpeg','Maria is a 2024 biographical psychological drama film directed by Pablo Larraín and written by Steven Knight. It is an international co-production between Italy, Chile, Germany and the United States. The film stars Angelina Jolie as opera singer Maria Callas, and follows the week before her death in 1977 in Paris, as she reflects on her life and career. It also stars Pierfrancesco Favino, Alba Rohrwacher, Haluk Bilginer, Stephen Ashfield, Valeria Golino, and Kodi Smit-McPhee in supporting roles. It is the third film in Larraín''s trilogy of iconic 20th-century women, following Jackie (2016), and Spencer (2021).
The film premiered at the 81st Venice International Film Festival on August 29, 2024, where it competed for the Golden Lion and received generally positive reviews from critics, who singled out Jolie''s performance for praise. It was released in select theaters in the United States on November 27, 2024, before streaming on Netflix on December 11. It was theatrically released in Italy by 01 Distribution on January 1, 2025, before its release in Germany by StudioCanal on February 6. The film earned a nomination for Best Cinematography at the 97th Academy Awards, while Jolie was nominated for Best Actress in a Motion Picture – Drama at the 82nd Golden Globe Awards.','https://en.wikipedia.org/wiki/Maria_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
