INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt15507512','The Piano Lesson',2024,'Drama','2024-tt15507512.webp','https://www.imdb.com/title/tt15507512/','https://en.wikipedia.org/wiki/File:The_Piano_Lesson_%282024_film%29_poster.jpg','The Piano Lesson is a 2024 American drama film directed by Malcolm Washington, who co-wrote the screenplay with Virgil Williams. It is an adaptation of the 1987 Pulitzer Prize-winning play by August Wilson. It stars an ensemble cast of Samuel L. Jackson, John David Washington, Ray Fisher, Michael Potts, Erykah Badu, Skylar Aleece Smith, Danielle Deadwyler, and Corey Hawkins.
The Piano Lesson premiered at the 51st Telluride Film Festival on August 31, 2024, and it was released in select theaters in the United States on November 8, 2024, before streaming on Netflix on November 22. 
The film received generally positive reviews from critics. Deadwyler was lauded for her performance, earning nominations for the Critics'' Choice Award and the Screen Actors Guild Award for Best Supporting Actress.','https://en.wikipedia.org/wiki/The_Piano_Lesson_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
