INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt27131358','We Live in Time',2024,'Drama','2024-tt27131358.webp','https://www.imdb.com/title/tt27131358/','https://en.wikipedia.org/wiki/File:We_live_in_time_poster.jpg','We Live in Time is a 2024 romantic drama film directed by John Crowley and written by Nick Payne. It follows the relationship of a couple, Tobias Durand (Andrew Garfield) and Almut Brühl (Florence Pugh), over the course of a decade. The film uses nonlinear narrative.
The film premiered at the Toronto International Film Festival on 6 September 2024. It was released in the United States on 11 October 2024 by A24 and on 1 January 2025 by StudioCanal in the United Kingdom and France. It has grossed $58.7 million worldwide, and received generally positive reviews from critics, particularly praising the performances and chemistry of Garfield and Pugh.','https://en.wikipedia.org/wiki/We_Live_in_Time','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
