INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt32086077','All We Imagine as Light',2024,'Drama','2024-tt32086077.webp','https://www.imdb.com/title/tt32086077/','https://en.wikipedia.org/wiki/File:All_We_Imagine_as_Light_film_poster.jpg','All We Imagine as Light (Malayalam: പ്രഭയായ് നിനച്ചതെല്ലാം, romanized: Prabhayaay Ninachathellam) is a 2024 drama film written and directed by Payal Kapadia. The cast includes Kani Kusruti, Divya Prabha, Chhaya Kadam, and Hridhu Haroon. Primarily in Malayalam, the film also features dialogue in Hindi and Marathi. It is an international co-production involving companies from France, India, the Netherlands, Luxembourg, and Italy.
The film had its world premiere at the main competition of the 77th Cannes Film Festival on 23 May 2024, where it was nominated for the Palme d''Or and won the Grand Prix. It was the first film from India to compete in the main competition since Swaham in 1994.
It received a limited release in Kerala, India, on 21 September 2024, before opening nationwide on 29 November 2024 to positive reviews. It topped the Sight & Sound poll for best film of 2024 and was named one of the top five international films of 2024 by the National Board of Review. At the 82nd Golden Globe Awards, the film received two nominations, for Best Foreign Language Film and Best Director. It was also nominated for the BAFTA Award for Best Film Not in the English Language.','https://en.wikipedia.org/wiki/All_We_Imagine_as_Light','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
