INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt32178949','The Seed of the Sacred Fig',2024,'Drama','2024-tt32178949.webp','https://www.imdb.com/title/tt32178949/','https://en.wikipedia.org/wiki/File:Les_Graines_du_figuier_sauvage_2024_film_poster.jpg','The Seed of the Sacred Fig (Persian: دانه‌ی انجیر معابد, romanized: Dāne-ye anjīr-e ma''ābed) is a 2024 political drama film written, co-produced and directed by Mohammad Rasoulof. Its plot centers on Iman, an investigating judge in the Revolutionary Court in Tehran, who grapples with paranoia as nationwide political protests, caused by the death of a young woman, intensify and his gun mysteriously disappears, making him distrust his wife and daughters. It stars Soheila Golestani, Missagh Zareh, Mahsa Rostami and Setareh Maleki. The fictional narrative is combined with real images of the 2022–2023 protests in Iran that were violently suppressed by Iranian authorities.
The Seed of the Sacred Fig had its world premiere in the main competition of the 77th Cannes Film Festival on 24 May 2024, where it won the Special Jury Prize. Ahead of its premiere, Rasoulof was sentenced to eight years in prison by Iranian authorities. After successfully fleeing to Germany, Rasoulof and other cast and crew members attended the Cannes'' red carpet premiere.
The film received critical acclaim and was theatrically released in France on 18 September 2024, and in Germany on 26 December 2024. It was named the Best International Film of 2024 by the National Board of Review. It was nominated for Best Motion Picture – Non-English Language at the 82nd Golden Globe Awards, as well as for Best Film Not in the English Language at the 78th British Academy Film Awards. At the 97th Academy Awards, it was nominated for Best International Feature Film as the German entry.','https://en.wikipedia.org/wiki/The_Seed_of_the_Sacred_Fig','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt14961016','I''m Still Here',2024,'Drama','2024-tt14961016.webp','https://www.imdb.com/title/tt14961016/','https://en.wikipedia.org/wiki/File:I%27m_Still_Here_%282024_film%29_poster.jpg','I''m Still Here (Portuguese: Ainda Estou Aqui ; Brazilian Portuguese: [aˈĩdɐ isˈtow aˈki]) is a 2024 political biographical drama film directed by Walter Salles from a screenplay by Murilo Hauser and Heitor Lorega, based on Marcelo Rubens Paiva''s 2015 memoir of the same name. It stars Fernanda Torres and Fernanda Montenegro as Eunice Paiva, a mother and activist coping with the forced disappearance of her husband, the dissident politician Rubens Paiva (Selton Mello), during the military dictatorship in Brazil. 
The film had its world premiere at the 81st Venice International Film Festival on 1 September 2024, where it won the Best Screenplay award and received critical acclaim with widespread praise for Torres'' performance. It was named one of the Top 5 International Films of 2024 by the National Board of Review. At the 82nd Golden Globe Awards, Torres won the Best Actress in a Motion Picture – Drama award while the film was nominated for Best Foreign Language Film, a category in which it was also nominated at the Critics'' Choice Movie Awards and the BAFTA. At the 97th Academy Awards, the film was nominated for Best Picture and Best Actress (Torres), and won Best International Feature Film, becoming the first-ever Brazilian-produced film to win an Academy Award.
Soon after its release in Brazilian theaters on 7 November 2024 by Sony Pictures Releasing International, the film was the target of an unsuccessful boycott by the Brazilian far-right, which denies that the military regime was a dictatorship. Grossing $36 million with a budget of around $9M, it became the highest-grossing Brazilian film since the COVID-19 pandemic.','https://en.wikipedia.org/wiki/I%27m_Still_Here_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
