INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt11891850','Hard Truths',2024,'Drama','2024-tt11891850.webp','https://www.imdb.com/title/tt11891850/','https://en.wikipedia.org/wiki/File:Hardtruths.jpg','Hard Truths is a 2024 drama film written and directed by Mike Leigh, starring Marianne Jean-Baptiste, Michele Austin, and David Webber. Set in London, its plot follows the plight of a depressed and nay-saying woman (Jean-Baptiste) and the relationship with her jovial sister Chantelle (Austin).
The film premiered at the 49th Toronto International Film Festival on 6 September 2024, and was met with widespread critical acclaim for its screenplay, direction and Jean-Baptiste''s performance. It was released theatrically in the United States on 6 December 2024, by Bleecker Street, in the United Kingdom on 31 January 2025 by StudioCanal, and in Spain on 28 February 2025 by BTeam Pictures. It was named one of the top 10 independent films of 2024 by the National Board of Review. Meanwhile, for her performance, Jean-Baptiste received Best Actress nominations at the Critics'' Choice Awards, BAFTA Film Awards, and the Gotham Awards, and swept the Best Actress trifecta at the NYFCC, LAFCA, and NSFC, becoming the first woman of colour to do so.','https://en.wikipedia.org/wiki/Hard_Truths','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
