INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt21823606','A Real Pain',2024,'Drama','2024-tt21823606.webp','https://www.imdb.com/title/tt21823606/','https://en.wikipedia.org/wiki/File:A_Real_Pain_%282024_film%29_poster.jpg','A Real Pain is a 2024 comedy-drama film produced, written and directed by Jesse Eisenberg. An international co-production between Poland and the United States, the film stars Eisenberg and Kieran Culkin as mismatched cousins who reunite for a Jewish heritage tour through Poland in honor of their late grandmother, but tensions between them surface amidst the backdrop of their family history. Its supporting cast includes Will Sharpe, Jennifer Grey, Kurt Egyiawan, Liza Sadovy, and Daniel Oreskes.
Principal photography took place primarily in Poland from May to June 2023. A Real Pain premiered at the 2024 Sundance Film Festival, where it won the Waldo Salt Screenwriting Award, and was released theatrically in the United States on November 1, 2024, and in Poland on November 8 by Searchlight Pictures. The film grossed $24.9 million worldwide.
A Real Pain was critically acclaimed and received several accolades, including two nominations at the 97th Academy Awards and 78th British Academy Film Awards, and four at the 82nd Golden Globe Awards; Culkin won the Oscar, BAFTA, SAG, Golden Globe and Critics'' Choice for Best Supporting Actor, while Eisenberg won the BAFTA Award for Best Original Screenplay. It was named as one of the top ten films of 2024 by the American Film Institute and the National Board of Review.','https://en.wikipedia.org/wiki/A_Real_Pain','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
