INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt29439114','The Room Next Door',2024,'Drama','2024-tt29439114.webp','https://www.imdb.com/title/tt29439114/','https://en.wikipedia.org/wiki/File:The_Room_Next_Door_poster.jpg','The Room Next Door (Spanish: La habitación de al lado) is a 2024 Spanish drama film written and directed by Pedro Almodóvar, in his English-language feature debut, based on the 2020 novel What Are You Going Through by Sigrid Nunez. Tilda Swinton and Julianne Moore star with John Turturro and Alessandro Nivola in supporting roles. The plot follows the relationship between two close friends (Swinton and Moore) as the former faces the prospect of ending her life due to terminal illness.
The film had its world premiere in the main competition of the 81st Venice International Film Festival on 2 September 2024, where it won the Golden Lion, a first for a Spanish film. It was released theatrically in Spain on 18 October 2024 by Warner Bros. Pictures. It won three Goyas (Best Adapted Screenplay, Best Cinematography, and Best Original Score) at the 39th Goya Awards.','https://en.wikipedia.org/wiki/The_Room_Next_Door','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
