INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt27403986','Juror #2',2024,'Drama','2024-tt27403986.webp','https://www.imdb.com/title/tt27403986/','https://en.wikipedia.org/wiki/File:Juror_No._2_%282024%29.jpg','A jury is a sworn body of people (jurors) convened to hear evidence, make findings of fact, and render an impartial verdict officially submitted to them by a court, or to set a penalty or judgment. Most trial juries are "petit juries", and consist of up to 15 people. Primarily in the United States, a larger jury known as a grand jury is used to investigate potential crimes and render indictments against suspects, and consists of between 16 and 23 jurors.
The jury system developed in England during the Middle Ages and is a hallmark of the English common law system. Juries are commonly used in countries whose legal systems derive from the British Empire, such as the United Kingdom, the United States, Canada, Australia, and Ireland. They are not used in most other countries, whose legal systems are based upon European civil law or Islamic sharia law, although their use has been spreading. Instead, typically guilt is determined by a single person, usually a professional judge. Civil law systems that do not use juries may use lay judges instead.
The word jury has also been applied to randomly-selected bodies with other purposes, such as citizen''s assemblies, otherwise known as policy juries.','https://en.wikipedia.org/wiki/Jury','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt8368368','The Apprentice',2024,'Drama','2024-tt8368368.webp','https://www.imdb.com/title/tt8368368/','https://en.wikipedia.org/wiki/File:The_Apprentice_%282024_film%29_poster.jpg','The Apprentice is a 2024 biographical drama film, directed by Ali Abbasi and written by Gabriel Sherman. It stars Sebastian Stan as Donald Trump and examines his career as a real estate businessman in New York City in the 1970s and 1980s, highlighting his relationship with attorney Roy Cohn, played by Jeremy Strong. The cast also includes Martin Donovan as Trump''s father Fred, and Maria Bakalova as Trump''s first wife, Ivana.
An international co-production between Canada, Denmark, Ireland, and the United States, the biopic was announced in May 2018, but languished until Abbasi, Stan, and Strong joined in 2023. It premiered at the 77th Cannes Film Festival on May 20, 2024, and impressed critics, sparking an eight-minute standing ovation, and "feverish media attention". However, the film struggled to find American distribution due to its subject matter and an attempt by Trump''s legal team to block its release. Briarcliff Entertainment eventually bought the rights, and theatrically released it on October 11, 2024. The film underperformed at the box office, grossing $17 million worldwide on a $16 million budget.
The film received praise from critics for its acting, directing, and editing; Trump himself, meanwhile, described it as a "defamatory, politically disgusting hatchet job" intended to harm his ultimately successful 2024 presidential campaign. For their performances, Stan and Strong each received wide acclaim and recognition, including respective nominations for Lead Actor and Supporting Actor at the 97th Academy Awards.','https://en.wikipedia.org/wiki/The_Apprentice_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
