INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt15939198','Blitz',2024,'Drama','2024-tt15939198.webp','https://www.imdb.com/title/tt15939198/','https://en.wikipedia.org/wiki/File:Blitz_film_poster.jpg','Blitz  is a 2024 historical war drama film about WWII written, produced and directed by Steve McQueen. The film stars Saoirse Ronan and Elliott Heffernan (in his film debut), supported by Harris Dickinson, Benjamin Clementine, Kathy Burke, Paul Weller, and Stephen Graham.
Blitz had its world premiere as the opening film at the BFI London Film Festival on 9 October 2024, and was released in selected cinemas in the United Kingdom and United States on 1 November 2024, followed by a streaming release on Apple TV+ on 22 November 2024. The film received generally positive reviews from critics.','https://en.wikipedia.org/wiki/Blitz_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
