INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt27367464','Kneecap',2024,'Drama','2024-tt27367464.webp','https://www.imdb.com/title/tt27367464/','https://en.wikipedia.org/wiki/File:Kneecap_poster.jpg','Kneecap is a 2024 biographical comedy-drama film written and directed by Rich Peppiatt, depicting the rise of Kneecap, an Irish hip-hop trio from Belfast, Northern Ireland. The film stars the band members Liam Óg Ó hAnnaidh, Naoise Ó Cairealláin, and JJ Ó Dochartaigh as themselves, with Josie Walker, Fionnuala Flaherty, Jessica Reynolds, Adam Best, Simone Kirby, and Michael Fassbender in supporting roles.
Kneecap premiered at the 2024 Sundance Film Festival on 18 January, the first film in the Irish language to do so, where it won the NEXT Audience Award. Its Irish premiere, at the 36th edition of the Galway Film Fleadh, won Best Irish Film, the Audience Award and the Irish Language Feature Film Award. The film was released on 2 August 2024 in the United States by Sony Pictures Classics, on 8 August 2024 in Ireland, and in the United Kingdom on 23 August, by Wildcard Distribution and Curzon Film, respectively. It received nominations in six categories at the 78th British Academy Film Awards and was selected as the Irish entry for the Academy Award for Best International Feature Film at the 97th Academy Awards, but was not nominated.','https://en.wikipedia.org/wiki/Kneecap_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
