The film had its world premiere at the Un Certain Regard section of the 2024 Cannes Film Festival, where it won the Jury Prize and the Performance Prize. It received eight nominations at the 50th César Awards, including Best Film, and won four awards: Best Supporting Actress (for Nina Meurisse), Best Male Revelation (for Sangaré), Best Original Screenplay and Best Editing.','https://en.wikipedia.org/wiki/Souleymane%27s_Story','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
