It had its world premiere at the 2024 Sundance Film Festival on January 21, 2024, and was released on August 9, 2024, by Metrograph Pictures. It received critical acclaim and was named one of the top 10 independent films of 2024 by the National Board of Review.','https://en.wikipedia.org/wiki/Good_One_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
