INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt22022452','Inside Out 2',2024,'Animation','2024-tt22022452.webp','https://www.imdb.com/title/tt22022452/','https://en.wikipedia.org/wiki/File:Inside_Out_2_poster.jpg','Inside Out 2 is a 2024 American animated coming-of-age film directed by Kelsey Mann and written by Meg LeFauve and Dave Holstein. Produced by Pixar Animation Studios for Walt Disney Pictures, it is the sequel to Inside Out (2015).  Amy Poehler, Phyllis Smith, Lewis Black, Diane Lane, and Kyle MacLachlan reprise their roles from the first film, with Maya Hawke, Kensington Tallman (replacing Kaitlyn Dias from the first film), Liza Lapira (replacing Mindy Kaling from the first film), Tony Hale (replacing Bill Hader from the first film), Ayo Edebiri, Lilimar, Grace Lu, Sumayyah Nuriddin-Green, Adèle Exarchopoulos, and Paul Walter Hauser joining the cast. The film follows Riley''s emotions unexpectedly joined by new emotions, eager to take control of her mind.
Development on Inside Out 2 began in early 2020, with Mann drawing inspiration from personal childhood experiences. The creative team initially explored a wider range of new emotions before narrowing the focus for narrative clarity, with Anxiety emerging as a central addition. Clinical psychologists, including Lisa Damour and Dacher Keltner, were consulted to ensure an accurate portrayal of adolescent emotional development, while a group of teenagers provided feedback on character and story authenticity. The film''s premise shifted during development from a talent show to Riley''s involvement in hockey. The production also marked the first Pixar feature scored by a woman, Andrea Datzman. Animation development emphasized spatial consistency through isometric mapping, and casting changes were driven in part by compensation disputes, resulting in the recasting of the characters Fear and Disgust.
Inside Out 2 premiered at the El Capitan Theatre in Hollywood, Los Angeles, on June 10, 2024, and was released in the United States on June 14. The film received positive reviews from critics and was a massive box office success, grossing $1.699 billion worldwide, breaking multiple box-office records, becoming the highest-grossing film by Pixar and the highest-grossing animated film of all time, though it was later overtaken by Ne Zha 2 (2025) just nine months after its initial release. It also became the highest-grossing film of 2024 and the eighth-highest-grossing film at the time of its release. The film received nominations for Best Animated Feature at the Golden Globes, Critics'' Choice, BAFTAs and Academy Awards. It additionally received a nomination for Cinematic and Box Office Achievement at the Golden Globes.','https://en.wikipedia.org/wiki/Inside_Out_2','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
