INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt29623480','The Wild Robot',2024,'Animation','2024-tt29623480.webp','https://www.imdb.com/title/tt29623480/','https://en.wikipedia.org/wiki/File:The_Wild_Robot_poster.jpg','The Wild Robot is a 2024 American animated science fiction film written and directed by Chris Sanders, based on the 2016 novel by Peter Brown. It was produced by DreamWorks Animation, and features the voices of Lupita Nyong''o, Pedro Pascal, Kit Connor, Bill Nighy, Stephanie Hsu, Matt Berry, Ving Rhames, Mark Hamill and Catherine O''Hara. The film follows a service robot shipwrecked on an island who must adapt to her surroundings, build relationships with the local wildlife and become the adoptive mother of an orphaned goose.
DreamWorks Animation bought the screenplay before the first novel''s release in 2016. Sanders first encountered the original book through his daughter and was offered an opportunity to direct a film adaptation at DreamWorks. The film''s visuals use a watercolor aesthetic, inspired by classic Disney animated films and the works of Hayao Miyazaki. Kris Bowers composed the score, marking his first score for a fully animated film. Development took four years on a budget of $78 million.
The Wild Robot premiered at the 49th Toronto International Film Festival on September 8, 2024, and was released in the United States on September 27, by Universal Pictures. The film received widespread acclaim from critics who praised it for its writing, animation, characters, score, visuals, emotional depth and voice acting. The film was a commercial success, grossing $334.5 million worldwide. Among its accolades, it received nine Annie Awards (including Best Animated Feature), won Best Animated Feature at the Critics'' Choice Awards and Producers Guild of America Awards, and was nominated for four Golden Globe Awards and three Academy Awards, becoming DreamWorks'' most-nominated film at the latter ceremony. A sequel based on Brown''s second book The Wild Robot Escapes is in development.','https://en.wikipedia.org/wiki/The_Wild_Robot','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
