INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt13622970','Moana 2',2024,'Animation','2024-tt13622970.webp','https://www.imdb.com/title/tt13622970/','https://en.wikipedia.org/wiki/File:Moana_2_poster.jpg','Moana 2 is a 2024 American animated adventure film directed by David Derrick Jr., Jason Hand, and Dana Ledoux Miller and written by Miller and Jared Bush. Produced by Walt Disney Animation Studios, it is the second animated film in the Moana franchise, following the 2016 film. Most of the principal cast members reprise their roles including Dwayne Johnson, Auliʻi Cravalho, Rachel House, Temuera Morrison, Nicole Scherzinger and Alan Tudyk. Set three years after the first film, it follows Moana reuniting with the demigod Maui and assembling a wayfinding crew to find the lost island of Motufetu, break its curse, and reconnect the people of the ocean.
A follow-up to 2016''s Moana was originally developed as a miniseries for Disney+, but by February 2024, it had been reworked into a theatrical sequel. Mark Mancina and Opetaia Foaʻi, the composers and co-songwriters of the first film, returned to score and co-write the songs, while Abigail Barlow and Emily Bear served as the main songwriters.
Moana 2 premiered at the Lanikuhonua Cultural Institute in Kapolei, Hawaii, on November 21, 2024, and was released by Walt Disney Studios Motion Pictures in the United States on November 27. The film received mixed reviews from critics and grossed $1.059 billion worldwide, outgrossing its predecessor and becoming the third highest-grossing film of 2024. It was nominated for Best Animated Feature Film at the 82nd Golden Globe Awards. A sequel is in development. A live-action remake to the first film was released in 2026.','https://en.wikipedia.org/wiki/Moana_2','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
