INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt4772188','Flow',2024,'Animation','2024-tt4772188.webp','https://www.imdb.com/title/tt4772188/','https://en.wikipedia.org/wiki/File:Flow_movie_poster.jpg','Flow (Latvian: Straume) is a 2024 independent animated dystopian adventure film directed by Gints Zilbalodis, written and produced by Zilbalodis and Matīss Kaža. A Latvian, French, and Belgian co-production, it features no dialogue and follows a cat trying to survive along with other animals in a seemingly post-apocalyptic world as the water level dramatically rises.
Production of Flow started in 2019 and lasted five and a half years. The animation was done using the free and open-source software Blender. Jacques Tati and Future Boy Conan served as inspirations for the film. No storyboards were used for the production, and there are no deleted scenes.
Flow premiered on 22 May 2024 at the Cannes Film Festival in the Un Certain Regard section and was released in Latvian theaters on 29 August. It received critical acclaim and broke several Latvian box-office records, becoming the most-viewed film in Latvian theaters in history. At the 97th Academy Awards, Flow won Best Animated Feature. It was also nominated for Best International Feature Film as Latvia''s submission, becoming the first film from Latvia to receive an Academy Award nomination and a win. Flow also won the Golden Globe Award for Best Animated Feature Film. Both of the award statuettes were put on display at the Latvian National Museum of Art.','https://en.wikipedia.org/wiki/Flow_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
