INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt23770030','Memoir of a Snail',2024,'Animation','2024-tt23770030.webp','https://www.imdb.com/title/tt23770030/','https://en.wikipedia.org/wiki/File:Memoir_of_a_Snail_poster.jpg','Memoir of a Snail is a 2024 Australian adult stop-motion animated tragicomedy film written, produced and directed by Adam Elliot. It stars the voices of Sarah Snook, Kodi Smit-McPhee, Eric Bana, Magda Szubanski, Dominique Pinon, Tony Armstrong, Paul Capsis, Nick Cave, and Jacki Weaver. The film''s plot, which is loosely inspired by Elliot''s own life, follows the trials and tribulations in the life of lonely misfit Grace Pudel, from childhood to adulthood.
The film had its world premiere at the 2024 Annecy International Animation Film Festival on 10 June 2024, and was released in Australia by Madman Entertainment on 17 October 2024. The film received critical acclaim and was nominated for Best Animated Feature at the 97th Academy Awards, the second R-rated animated film to be nominated after Anomalisa (2015), another stop-motion film.','https://en.wikipedia.org/wiki/Memoir_of_a_Snail','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
