INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt17163970','Wallace & Gromit: Vengeance Most Fowl',2024,'Animation','2024-tt17163970.webp','https://www.imdb.com/title/tt17163970/','https://en.wikipedia.org/wiki/File:Vengeance_Most_Fowl_poster.jpg','Wallace & Gromit: Vengeance Most Fowl is a 2024 British stop-motion animated comedy film directed by Nick Park and Merlin Crossingham and written by Park and Mark Burton. The sixth installment in the Wallace & Gromit series and the second to be feature-length, the story features the return of Feathers McGraw from The Wrong Trousers (1993), who hijacks Wallace''s latest invention, a robotic garden gnome named Norbot, as part of a plot for revenge. Produced by Aardman Animations, Ben Whitehead portrays Wallace in his first feature-length appearance following the death of the original actor, Peter Sallis, in 2017. The remaining voice cast consists of Peter Kay, Lauren Patel and Reece Shearsmith.
Owing to difficulties with working with DreamWorks Animation during the production of The Curse of the Were-Rabbit (2005), Park was hesitant to direct another Wallace & Gromit feature film for several years. Announced in January 2022, Vengeance Most Fowl was conceived as another 30-minute short before expanding into a feature. The score was composed by Lorne Balfe and Julian Nott.
Wallace & Gromit: Vengeance Most Fowl premiered at the American Film Institute on 27 October 2024. It was broadcast on BBC One and BBC iPlayer on 25 December in the UK and released on Netflix internationally on 3 January 2025. After twenty-eight days, it became the BBC''s most watched scripted show since 2002. The film received acclaim, holding a 100% rating on the review aggregator website Rotten Tomatoes. It was nominated in the Animated Feature categories at the Academy Awards, Golden Globe Awards and Annie Awards. At the BAFTAs, it won the inaugural award for Children''s & Family Film, as well as the award for Animated Film, and was nominated for Outstanding British Film.','https://en.wikipedia.org/wiki/Wallace_%26_Gromit:_Vengeance_Most_Fowl','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
