INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt7510222','Despicable Me 4',2024,'Animation','2024-tt7510222.webp','https://www.imdb.com/title/tt7510222/','https://en.wikipedia.org/wiki/File:Despicable_Me_4_Theatrical_Release_Poster.jpeg','Despicable Me 4 is a 2024 American animated comedy film directed by Chris Renaud and written by Mike White and Ken Daurio. Produced by Illumination and Universal Pictures, it is the fourth main installment in the Despicable Me franchise and the sixth overall installment. The film stars the voices of Steve Carell, Kristen Wiig, Pierre Coffin, Joey King, Miranda Cosgrove, Stephen Colbert, Sofía Vergara, and Will Ferrell. Taking place after the events of Despicable Me 3 (2017), the film sees reformed supervillain and secret agent Gru temporarily relocating his family to a safe house when his old rival, Maxime Le Mal (Ferrell), seeks revenge. Meanwhile, some of Gru''s Minions are augmented with superpowers from the Anti-Villain League (AVL), forming a superhero initiative known as the Mega Minions.
Development on a fourth main Despicable Me film began in September 2017. It was officially confirmed in February 2022, with Renaud, Patrick Delage, and White attached as director, co-director, and writer, respectively. Production was underway by June 2022. Most of the main voice cast was announced in January 2024, with Brett Hoffman and Daurio revealed as co-producer and co-writer, respectively, with Chris Meledandri and White. Heitor Pereira and Pharrell Williams returned from previous instalments to compose the score and write original songs and themes, respectively.
Despicable Me 4 debuted at the Jazz at Lincoln Center in New York on June 9, 2024, and was theatrically released in the United States on July 3 by Universal Pictures. Despite mixed reviews, the film continued the franchise''s streak of box-office successes, grossing $986.7 million worldwide against a budget of $100 million, making it the fourth-highest-grossing film of 2024.','https://en.wikipedia.org/wiki/Despicable_Me_4','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
