INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt21692408','Kung Fu Panda 4',2024,'Animation','2024-tt21692408.webp','https://www.imdb.com/title/tt21692408/','https://en.wikipedia.org/wiki/File:Kung_Fu_Panda_4_poster.jpg','Kung Fu Panda 4 is a 2024 American animated martial arts comedy film directed by Mike Mitchell and written by Darren Lemke, Jonathan Aibel and Glenn Berger. Produced by DreamWorks Animation, it is the fourth installment in the Kung Fu Panda franchise and the sequel to Kung Fu Panda 3 (2016). It features Jack Black, Bryan Cranston, James Hong, Ian McShane, and Dustin Hoffman reprising their roles from the previous films. In the film, Po—who must find and train his successor as the new Dragon Warrior—teams up with fox bandit Zhen to defeat evil sorceress The Chameleon, who plans to steal the kung fu skills of every deceased master in China.
DreamWorks announced the fourth film in August 2022, with Mitchell, Stephanie Ma Stine, and Rebecca Huntley attached as director, co-director, and producer, respectively, by April 2023. In December 2023, most of the main voice cast, along with the return of Aibel and Berger as writers and co-producers, were confirmed. Lemke''s involvement was confirmed in February 2024. Composer Hans Zimmer, who had scored for the previous three installments, returned as composer alongside frequent collaborator Steve Mazzaro.
Kung Fu Panda 4 premiered at the AMC 14 Theater at The Grove in Los Angeles on March 3, 2024, and was theatrically released in the United States on March 8 by Universal Pictures. The film received mostly positive reviews from critics and proved commercially successful, grossing $547.7 million worldwide on an $85 million budget and outgrossing its predecessor to rank as the ninth-highest-grossing film of 2024. It earned three nominations at the 52nd Annie Awards, as well as a nomination for Best Animated Feature at the 52nd Saturn Awards.','https://en.wikipedia.org/wiki/Kung_Fu_Panda_4','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
