INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt8864596','Transformers One',2024,'Animation','2024-tt8864596.webp','https://www.imdb.com/title/tt8864596/','https://en.wikipedia.org/wiki/File:Transformers_One_Official_Poster.jpg','Transformers One is a 2024 American animated science fiction action film based on Hasbro''s Transformers toy line. Directed by Josh Cooley and written by Eric Pearson, Andrew Barrer and Gabriel Ferrari, the film stars Chris Hemsworth, Brian Tyree Henry, Scarlett Johansson, Keegan-Michael Key, Steve Buscemi, Laurence Fishburne, and Jon Hamm. It depicts the origins of Optimus Prime and Megatron.
In March 2015, following the release of Transformers: Age of Extinction (2014), Paramount Pictures tasked Akiva Goldsman to set up a writers'' room to create ideas for potential future Transformers films. By May 2015, Barrer and Ferrari had signed on as writers, and they came up with the idea of an animated prequel set on Cybertron. The film was announced in August 2017, and by April 2020, Cooley had been hired to direct. Animation services were provided by Industrial Light & Magic, and the design was primarily influenced by the Generation 1 era and Art Deco. The score was composed by Brian Tyler.
Transformers One premiered in Sydney, Australia, on September 11, 2024, and was released by Paramount Pictures in the United States on September 20. The film received positive reviews from critics but underperformed at the box office, grossing $129 million worldwide on a budget of $75–147 million.','https://en.wikipedia.org/wiki/Transformers_One','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
