INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt31711040','Look Back',2024,'Animation','2024-tt31711040.webp','https://www.imdb.com/title/tt31711040/','https://ameblo.jp/andesumashinogogo/entry-12874964177.html','Look Back (Japanese: ルックバック, Hepburn: Rukku Bakku) is a 2024 Japanese animated coming-of-age drama film based on the one-shot web manga of the same name by Tatsuki Fujimoto. The film is directed by Kiyotaka Oshiyama, who also wrote the screenplay and served as a character designer, and produced by Studio Durian. It stars Yuumi Kawai and Mizuki Yoshida as two girls with a passion for drawing—the outgoing Fujino (Kawai) and the truant recluse Kyomoto (Yoshida), the latter of whose artistic ability inspires a competitive fervor in Fujino that soon develops into a partnership. 
Look Back premiered at the 2024 Annecy International Animation Film Festival. It was theatrically released in Japan by Avex Pictures on 28 June 2024.','https://en.wikipedia.org/wiki/Look_Back_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
