INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt31064841','Piece by Piece',2024,'Animation','2024-tt31064841.webp','https://www.imdb.com/title/tt31064841/','https://en.wikipedia.org/wiki/File:Piece_by_Piece_final_poster.jpeg','Piece by Piece is a 2024 American animated biographical documentary comedy film co-produced, co-written and directed by Morgan Neville. It follows the life and career of American musician Pharrell Williams, who stars in the film, through the lens of Lego animation, or brickfilm. Produced by Neville''s Tremolo Productions, Williams'' I Am Other, and in association with The Lego Group, Piece by Piece marks the sixth theatrical Lego-based film and the first under Universal Pictures'' run of their film rights. Alongside Williams and Neville, the film stars the voices of Gwen Stefani, Kendrick Lamar, Timbaland, Justin Timberlake, Busta Rhymes, Jay-Z, and Snoop Dogg as Lego versions of themselves.
Williams had considered creating a film about his life since 2013; however, serious plans for a documentary in animated musical form started in 2019 following a discussion between Williams and Neville. Neville interviewed with Williams'' associates remotely during the COVID-19 pandemic, and later shot certain live-action scenes with him. The Lego Group created minifigure pieces that better represent the styles of African-American culture, as well as Williams''s frequent collaborators, and designed new pieces for music equipment. Williams, who also produces, wrote five original songs for the film.
Piece by Piece premiered at the 51st Telluride Film Festival on August 30, 2024, and was released theatrically in the United States and Canada on October 11 through Focus Features, with Universal handling international distribution. The film received generally positive reviews from critics and grossed $10.7 million against a $16 million budget.','https://en.wikipedia.org/wiki/Piece_by_Piece_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
