INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt27902121','Super/Man: The Christopher Reeve Story',2024,'Documentary','2024-tt27902121.webp','https://www.imdb.com/title/tt27902121/','https://en.wikipedia.org/wiki/File:SuperMan_The_Christopher_Reeve_Story_poster.jpg','Super/Man: The Christopher Reeve Story is a 2024 documentary film about the life of American actor Christopher Reeve after a horse riding accident left him paralyzed, and his subsequent work as an activist for disability rights. The documentary was directed by Ian Bonhôte and Peter Ettedgui, who co-wrote the script with Otto Burnham; its title is a reference to Reeve''s role as Superman in the 1978–1987 Superman films. Reeve''s children Matthew, Alexandra, and Will are featured in the film.
A British-American venture, the film is a co-production by Words + Pictures, Passion Pictures, and Misfits Entertainment in association with Jenco Films, and was acquired for distribution by Warner Bros. Pictures, DC Studios, HBO Documentary Films, CNN Films, and the streaming service Max. Super/Man: The Christopher Reeve Story premiered on January 19, 2024, at the Sundance Film Festival, and received a limited theatrical release in collaboration with Fathom Events in the United States on September 21 and 25, 2024. The film was wide released in North America on October 11.
The documentary was met with widespread acclaim from critics and audiences alike, and was named as one of the top five documentary films of 2024 by the National Board of Review. It received numerous accolades, including winning for Best Documentary at the British Academy Film Awards and the Producers Guild of America, and six awards at the Critics'' Choice Documentary Awards (including Best Documentary Feature).','https://en.wikipedia.org/wiki/Super/Man:_The_Christopher_Reeve_Story','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
