INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt30321133','Will & Harper',2024,'Documentary','2024-tt30321133.webp','https://www.imdb.com/title/tt30321133/','https://en.wikipedia.org/wiki/File:Will_%26_Harper_film_poster.jpg','Will & Harper is a 2024 American documentary film directed by Josh Greenbaum and following actor Will Ferrell and writer Harper Steele as the duo make a 17-day road trip across the United States, the latter having recently completed a gender transition. It was produced by Jessica Elbaum, Ferrell, Greenbaum, Christopher Leggett, and Rafael Marmor.
Will & Harper premiered at the 40th Sundance Film Festival on January 22, 2024, received a limited theatrical release in the United States on September 13, and began streaming worldwide on Netflix on September 27. It received positive reviews from critics and was named one of the top 5 documentary films of 2024 by the National Board of Review. The film won a Peabody Award at the 85th Annual Ceremony. The film received a BAFTA nomination for Best Documentary at the 2025 BAFTA Film Awards.','https://en.wikipedia.org/wiki/Will_%26_Harper','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
