A co-production between Palestine and Norway, the film was selected for the Panorama section at the 74th Berlin International Film Festival, where it had its world premiere on 16 February 2024, winning the Panorama Audience Award for Best Documentary Film and the Berlinale Documentary Film Award. The film also won the Academy Award for Best Documentary Feature Film at the 97th Academy Awards.','https://en.wikipedia.org/wiki/No_Other_Land','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
