INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt31015216','Dahomey',2024,'Documentary','2024-tt31015216.webp','https://www.imdb.com/title/tt31015216/','https://en.wikipedia.org/wiki/File:Dahomey_film_poster.jpg','Dahomey is a 2024 documentary film directed by Mati Diop. It is a dramatised account of 26 royal treasures from the Kingdom of Dahomey (in modern-day Benin), which were held in a museum in France. The film explores how the artifacts were returned from France to Benin, and the reactions of Beninese people. The film was an international co-production between companies in France, Senegal, and Benin.
The film had its world premiere at the main competition of the 74th Berlin International Film Festival, where it won the festival''s top prize, the Golden Bear. It was released theatrically in France on 11 September 2024, by Les Films du Losange, to critical acclaim. It was named one of the Top 5 Documentary Films of 2024 by the National Board of Review. 
It was also selected as the Senegalese entry for Best International Feature Film at the 97th Academy Awards, where it was shortlisted in two categories: Documentary Feature Film and International Feature Film.','https://en.wikipedia.org/wiki/Dahomey_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
