INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt1262426','Wicked',2024,'Musical','2024-tt1262426.webp','https://www.imdb.com/title/tt1262426/','https://en.wikipedia.org/wiki/File:Wicked_%282024_film%29_poster.png','Wicked (titled on-screen as Wicked: Part I) is a 2024 American musical fantasy film directed by Jon M. Chu and written by Winnie Holzman and Dana Fox. It adapts the first act of the 2003 stage musical by Stephen Schwartz and Holzman, which was loosely based on Gregory Maguire''s 1995 novel, a re-imagining of L. Frank Baum''s 1900 novel The Wonderful Wizard of Oz and its 1939 film adaptation. Cynthia Erivo and Ariana Grande star as Elphaba Thropp and Glinda Upland, respectively; while Jonathan Bailey, Ethan Slater, Bowen Yang, Peter Dinklage, Michelle Yeoh, and Jeff Goldblum appear in supporting roles. Set in the Land of Oz before the events of The Wonderful Wizard of Oz, the film explores the early relationship between Elphaba, the future Wicked Witch of the West, and her schoolmate Galinda, who becomes Glinda the Good.
Universal Pictures and Marc Platt, who both produced the stage musical, announced the film adaptation in 2012. After a long development and multiple delays, partly due to the COVID-19 pandemic, Chu was hired to direct, with Erivo and Grande cast in 2021. The adaptation was split into two parts to avoid omitting plot points and further develop the characters. Principal photography on both films began in England in December 2022, was interrupted in July 2023 by the 2023 SAG-AFTRA strike, and resumed and concluded in January 2024.
Wicked premiered at the State Theatre in Sydney on November 3, 2024, and was released in the United States on November 22. It was critically and commercially successful, grossing $764 million worldwide on a $150 million budget and becoming the highest-grossing Oz film, the highest-grossing musical film adaptation, and the fifth-highest-grossing film of 2024. The film was declared a pop culture phenomenon and was listed as one of the best musical films of the 21st century. Among its various accolades, Wicked earned ten nominations at the 97th Academy Awards (including Best Picture), winning Best Costume Design and Best Production Design. It also received three awards from the National Board of Review (including Best Film) and was listed among the top ten films of 2024 by the American Film Institute. The sequel, Wicked: For Good, was released on November 21, 2025.','https://en.wikipedia.org/wiki/Wicked_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt13186482','Mufasa: The Lion King',2024,'Musical','2024-tt13186482.webp','https://www.imdb.com/title/tt13186482/','https://en.wikipedia.org/wiki/File:Mufasa_The_Lion_King_Movie_2024.jpeg','Mufasa: The Lion King is a 2024 American musical drama film produced by Walt Disney Pictures. The photorealistically animated film serves as a prequel and sequel to The Lion King (2019), which itself is a remake of the 1994 animated film. Directed by Barry Jenkins from a screenplay written by Jeff Nathanson, the film''s cast includes Seth Rogen, Billy Eichner, Donald Glover, Beyoncé Knowles-Carter, and John Kani reprising their roles from the remake; new cast members include Aaron Pierre, Kelvin Harrison Jr., Tiffany Boone, Mads Mikkelsen, Thandiwe Newton, Lennie James, Anika Noni Rose, and Blue Ivy Carter in her feature film debut. It features Rafiki recounting to Simba and Nala''s cub, Kiara, the history of Mufasa, including how he first met Scar and other allies, his battle against a renegade pride of white lions, and the journey that led him to become King of the Pride Lands.
Development on a prequel to The Lion King was confirmed in September 2020, with Jenkins attached to direct and Nathanson finishing a draft of the script. Pierre and Harrison were announced as the voice cast in August 2021, followed by further casting between September 2022 and April 2024. The film was officially announced when its official title was revealed in September 2022 at the 2022 D23 Expo announcement. Production on the film slowed down in July 2023 due to the 2023 SAG-AFTRA strike. The film is dedicated to James Earl Jones, the voice of Mufasa in the 1994 film and remake, who died three months before the film''s release; as a tribute, his voice is heard briefly during the opening titles.
Mufasa: The Lion King premiered on December 9, 2024, at the Dolby Theatre in Los Angeles, and was distributed in the United States by Walt Disney Studios Motion Pictures on December 20. The film received mixed reviews from critics who praised the visual effects, vocal performances, and Jenkins'' direction but were critical of the screenplay. It grossed $723 million, making it the sixth-highest-grossing film of 2024.','https://en.wikipedia.org/wiki/Mufasa:_The_Lion_King','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt14260836','Better Man',2024,'Musical','2024-tt14260836.webp','https://www.imdb.com/title/tt14260836/','https://en.wikipedia.org/wiki/File:Better_Man_film_poster.jpg','Better Man is a 2024 biographical jukebox musical drama film directed by Michael Gracey from a screenplay by Gracey, Simon Gleeson and Oliver Cole. It is based on the life of the English singer Robbie Williams and stars Williams, Jonno Davies, Steve Pemberton and Alison Steadman, and is a co-production between Australia, China, France, the United Kingdom and the United States.
Development on Better Man began in February 2021, after Gracey was announced as director and co-writer alongside Gleeson and Cole. Williams is portrayed as an anthropomorphic chimpanzee, performed by Davies using motion capture, and co-voiced by Williams: this was due to Williams'' perception of himself as a "performing monkey" and Gracey''s vision of the film as a "satirical musical". No character comments on his appearance. Williams also re-recorded several songs from his discography for the film. Principal photography began in May 2022 and lasted until June 2023, with filming locations including Docklands Studios in Melbourne, Regent Street and the Royal Albert Hall in London.
Better Man premiered at the 51st Telluride Film Festival on 30 August 2024 and was theatrically released in the United States on 25 December, by Paramount Pictures, and in the United Kingdom and Australia a day later, respectively by Entertainment Film Distributors and Roadshow Films. It grossed $22.5 million worldwide, becoming a box-office bomb, but received positive reviews. Better Man won nine AACTA Awards, including for Best Film, and was nominated for Best Visual Effects at the Academy Awards, Critics'' Choice Awards, BAFTA Film Awards and Visual Effects Society Awards.','https://en.wikipedia.org/wiki/Better_Man_(film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt21382296','Carry-On',2024,'Thriller','2024-tt21382296.webp','https://www.imdb.com/title/tt21382296/','https://bleedingcool.com/movies/carry-on-trailer-poster-and-2-images-for-netflixs-holiday-thriller/','Carry-On is a 2024 American action thriller film directed by Jaume Collet-Serra and written by T. J. Fixman. The film stars Taron Egerton, Sofia Carson, Danielle Deadwyler, and Jason Bateman. Its plot follows a young TSA officer who is blackmailed into allowing a nerve agent on board a flight during Christmas Eve in order to kill 250 people.  
Carry-On was released by Netflix on December 13, 2024, received positive reviews from critics, and earned more views during its opening week than any other film released on Netflix in 2024.','https://en.wikipedia.org/wiki/Carry-On','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt26625693','The Order',2024,'Thriller','2024-tt26625693.webp','https://www.imdb.com/title/tt26625693/','https://en.wikipedia.org/wiki/File:The_Order_2024_film_poster.jpg','The Order is a 2024 crime thriller film directed by Justin Kurzel and written by Zach Baylin, based on the 1989 non-fiction book The Silent Brotherhood by Kevin Flynn and Gary Gerhardt. The film revolves around FBI agent Terry Husk (Jude Law) who goes after a white supremacist terrorist group known as the Order, led by Robert Jay Mathews (Nicholas Hoult), that was active in the United States in the 1980s. Tye Sheridan, Jurnee Smollett, Alison Oliver, and Marc Maron appear in supporting roles.
The film had its world premiere at the 81st Venice International Film Festival on August 31, 2024, where it competed for the Golden Lion. It received a limited theatrical release in the United States on December 6, 2024, and was released worldwide on the streaming platform Amazon Prime Video. It received generally positive reviews from critics.','https://en.wikipedia.org/wiki/The_Order_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt11301886','Rebel Ridge',2024,'Thriller','2024-tt11301886.webp','https://www.imdb.com/title/tt11301886/','https://en.wikipedia.org/wiki/File:Rebel_Ridge_film_poster.jpg','Rebel Ridge is a 2024 American action thriller film written, produced, directed and edited by Jeremy Saulnier. The film stars Aaron Pierre as Terry Richmond, a former Marine; he has the funds needed to post bail for his cousin, but the money is unjustly seized via civil forfeiture by a small town''s corrupt police force. Don Johnson, AnnaSophia Robb, David Denman, Emory Cohen, Steve Zissis, Zsané Jhé, Dana  Lee, and James Cromwell also appear in the film.
Rebel Ridge was released by Netflix on September 6, 2024 to positive critical reviews. It won the Critics'' Choice Television Award for Best Movie Made for Television and the Primetime Emmy Award for Outstanding Television Movie.','https://en.wikipedia.org/wiki/Rebel_Ridge','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt14858658','Blink Twice',2024,'Thriller','2024-tt14858658.webp','https://www.imdb.com/title/tt14858658/','https://en.wikipedia.org/wiki/File:Blink_Twice_poster.jpeg','Blink Twice is a 2024 American psychological thriller film directed and produced by Zoë Kravitz (in her directorial debut) from a script she wrote with E.T. Feigenbaum. The film stars Naomi Ackie, Channing Tatum, Christian Slater, Simon Rex, Adria Arjona, Haley Joel Osment, Kyle MacLachlan, Geena Davis, and Alia Shawkat. It tells the story of a group of people invited to the private island of a billionaire tech mogul as something strange and sinister happens with the attendees.
Blink Twice premiered at the DGA Theater in Los Angeles on August 8, 2024, and was released in the United States on August 23 by Amazon MGM Studios. The film grossed $48 million worldwide on a $20 million production budget, and received generally positive reviews from critics.','https://en.wikipedia.org/wiki/Blink_Twice','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
--> statement-breakpoint
INSERT INTO pix_movie_stats (imdb_id,title,release_year,genre,poster_key,source_url,poster_source_url,synopsis,synopsis_source_url,attributes_json,wins,losses,appearances,unseen_count,game_appearances_json,created_at,updated_at) VALUES ('tt26753003','Trap',2024,'Thriller','2024-tt26753003.webp','https://www.imdb.com/title/tt26753003/','https://en.wikipedia.org/wiki/File:Trap_2024_%28film_poster%29.jpg','Trap is a 2024 American thriller film produced, written, and directed by M. Night Shyamalan. The film stars Josh Hartnett, Ariel Donoghue, Shyamalan''s daughter Saleka Night, Hayley Mills, and Alison Pill. The film follows Cooper Abbott, a serial killer known as the Butcher, who attends a concert with his teenage daughter Riley, only to discover the event has been intercepted by police who have been tipped off that he would be present.
The film was shot in Canada in late 2023. It premiered in New York City on July 24, 2024, and was theatrically released in the United States by Warner Bros. Pictures on August 2, 2024. It received mixed reviews from critics and grossed $83 million on a $30 million budget.','https://en.wikipedia.org/wiki/Trap_(2024_film)','{}',0,0,0,0,'{}',CAST(strftime('%s','now') AS INTEGER) * 1000,CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(imdb_id) DO UPDATE SET title=excluded.title,release_year=excluded.release_year,genre=excluded.genre,poster_key=excluded.poster_key,source_url=excluded.source_url,poster_source_url=CASE WHEN excluded.poster_source_url<>'' THEN excluded.poster_source_url ELSE pix_movie_stats.poster_source_url END,synopsis=CASE WHEN excluded.synopsis<>'' THEN excluded.synopsis ELSE pix_movie_stats.synopsis END,synopsis_source_url=CASE WHEN excluded.synopsis_source_url<>'' THEN excluded.synopsis_source_url ELSE pix_movie_stats.synopsis_source_url END,updated_at=excluded.updated_at;
